INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cosmic Osmo and the Worlds Beyond the Mackerel', 'You''re an Osmo, a strange creature indeed. You explore the galaxy in your spaceship, and the planets you encounter are almost as bizarre as the Osmos themselves. There are seven worlds presented for your consideration, each more goofy and peculiar than the last. Cosmic Osmo is a game about exploration and discovery, not winning or challenges.' FROM games WHERE igdb_id = 16200 ON CONFLICT (game_id, language_code) DO NOTHING;
