INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hellfire', 'In the year 2998, humanity has finally reached the stars, and was able to build a prosperous, peaceful society. However, a space matter known as the Black Nebula began to spread, threatening to engulf the galaxies controlled by humans. It turned out that a robotic dictator named Super Mech was behind this occurrence. The Earth sends Captain Lancer, a skillful pilot navigating the powerful CNCS1 aircraft, equipped with the most powerful weapon: the Hellfire... This is a horizontal space shooter, with the traditional premise of a lone pilot traversing hostile areas and out-manoeuvring and/or destroying quick and numerous enemies.' FROM games WHERE igdb_id = 19503 ON CONFLICT (game_id, language_code) DO NOTHING;
