INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('leisure-suit-larry-iii-passionate-patti-in-pursuit-of-the-pulsating-pectoral', 2908, '1989-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2kcg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/argc3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Leisure Suit Larry III: Passionate Patti in Pursuit of the Pulsating Pectoral', 'Passionate Patti in Pursuit of the Pulsating Pectorals! is the third game in Al Lowe''s Leisure Suit Larry series. Larry Laffer has finally found the woman of his dreams, and can happily live with her together on the beautiful tropical island... until he gets thrown out of the house by his wife. His boss, who happens to be his (now ex-) father-in-law, fires him. Larry is all alone, without a woman, without a job, on an island that has long ceased to be a "tropical paradise" and is exploited by entertainers, lawyers, and alike. But never despair! Dressed in his irresistible leisure suit, Larry is about to conquer the world (or at least its female population) anew. Watch out, fairer sex, because Larry is back to his swinging self!' FROM games WHERE igdb_id = 2908 ON CONFLICT (game_id, language_code) DO NOTHING;
