INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Indiana Jones and the Last Crusade: The Graphic Adventure', 'Europe, 1938. The Lost Ark was just a warm up! Now Adolph Hitler is after the most powerful talisman of all- the Holy Grail. A few brave men stand in his way. Fortunately, one of them is Indiana Jones. And this time, he has his dad with him. The bad guys are in your face all the way- Nazis, mercenaries, traitors, spies. Not to mention everything the Luftwaffe can throw at you.. Can you handle the heat? If you can, you just might earn a higher I.Q. (Indy Quotient) than the man with the whip and the hat. Puzzles, action, adventure.' FROM games WHERE igdb_id = 186 ON CONFLICT (game_id, language_code) DO NOTHING;
