INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mia-missing-in-action', 40080, '1989-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4isv.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'M.I.A. Missing in Action', 'The player takes on the role of a US Army special operations soldier infiltrating enemy POW camps in Vietnam to find prisoners of wars and lead them to freedom. Like its predecessor, there are a total of six levels in the game: war-torn field, jungle, airstrip, rail-yard, POW camp, and escaping POW camp. M.I.A. can be played by up to two players, with Player 1 in green and Player 2 in blue. Throughout most of the game, the player''s main weapon is a knife, which is capable of destroying any enemy in the game. By killing the red enemy soldiers, the player can acquire additional weapons. The available weapons consist of an assault rifle (12 rounds), a flamethrower (2 rounds), a bazooka (3 rounds), and grenades (3 rounds). Unlike Green Beret, the player can carry more than one weapon and switch between them at will. If the player loses a life, then only their currently equipped weapon will be lost. At the end of each level, an assorted amount of troops on fixed machine gun positions (usually four) that must be eliminated. On the last mission of the game, the freed hostages are susceptible to being slain by enemies; if all the POW''s get killed then "MISSION FAILED" flashes on the screen and the game is permanently over.' FROM games WHERE igdb_id = 40080 ON CONFLICT (game_id, language_code) DO NOTHING;
