INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ballistix', 'Ballistix is a video game created by Martin Edmondson for the Amiga and Atari ST and published by Psyclapse in 1989. It was also converted to a number of other home computers in the same year and the PC Engine/TurboGrafx-16 console in 1991. It is a fictional futuristic sport involving directing a puck to a goal by shooting small balls at it.' FROM games WHERE igdb_id = 5878 ON CONFLICT (game_id, language_code) DO NOTHING;
