INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('darius-ii', 39695, '1989-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2eyh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7zf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darius II', 'Darius II is a 1989 arcade video game developed by Taito. It is the direct sequel to the 1987 Darius. It was later released as Sagaia in Japan in 1991 for the Game Boy as well as non-Japanese ports. A remake was released for the PC Engine Super CD-ROM as Super Darius II in 1993. A Mega Drive conversion was released in Japan in 1990; it was later released for the Genesis in the United States and Brazil in 1991, where it was renamed Sagaia. Changes include a boss rush mode (via a code) and various modifications to levels and mechanics, such as the boss Steel Spine being moved to another level and the boss Killer Higia being replaced with a similar creation called Nehonojia. This conversion does not support two players, so the ability to choose between Proco Jr. and Tiat Young was added; Proco plays like normal, while Tiat starts every life off with one power level to every weapon. A Master System conversion, developed by Natsume, was released in Europe and Brazil in 1992, also titled Sagaia. It is somewhat based on the Mega Drive port, and while Tiat Young and her abilities are still present (though even more limited), many zones (and thus bosses) have been completely removed. The Super CD-ROM version features an entirely new set of bosses, major changes to levels, and a fully arranged soundtrack including new songs.' FROM games WHERE igdb_id = 39695 ON CONFLICT (game_id, language_code) DO NOTHING;
