INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alex Kidd in the Enchanted Castle', 'The whole Kidd family is upset! Alex’s father, King Thor, is missing, and they suspect he has been kidnapped by Ashra, the mean ruler of the planet Paperock. Alex speeds to Paperock to investigate, but the creatures of Paperock decide to hinder his efforts and try to keep him away from Sky Castle, Ashra’s hideaway. Luckily Alex knows how to jump, punch and kick his way through the most stubborn of enemies.' FROM games WHERE igdb_id = 3217 ON CONFLICT (game_id, language_code) DO NOTHING;
