INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alleyway', 'Interstellar ping-pong with a deadly energy ball! Your spaceship is at the gate of the Alleyway. Use your vessel to repel the energy ball. Atomize space grids with your return shots. Destroy the entire field and move on to even more challenging targets. You''re in command in the Alleyway!' FROM games WHERE igdb_id = 7751 ON CONFLICT (game_id, language_code) DO NOTHING;
