INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Explorer', 'Dungeon Explorer is a multiplayer action/role-playing game where up to five players can play at the same time. You, brave soldier, are the last hope of a once-peaceful Oddesia. Yours is a strange world full of magic, hidden dangers and potions. But you have powerful friends. Use them to recover the ORA Stone which was hidden from the conquering evil king, Natas. Deep within the ancient dungeons lies the Stone with powers of life, light, happiness. But where?' FROM games WHERE igdb_id = 74314 ON CONFLICT (game_id, language_code) DO NOTHING;
