INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('drakkhen', 12057, '1989-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3b7q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arv45.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drakkhen', 'The prophecy has been fulfilled. The world shall be ruled by the dragons. On an island far away, their lords prepare for the conquest of the lands. There is only one hope for mankind. The emperor sends out four heroes -- warriors and magicians -- to solve the puzzle of tears and prevent the invasion of the Drakkhen. Drakkhen is a role-playing game with a visual presentation that combines 3D landscapes and 2D interiors. The player''s party will travel overland on a flat terrain made up of vectors, on which 2D objects are zoomed (The same type of engine was later used in Eternam). The player will encounter monsters and fight them in real-time combat, and discover the palaces of the dragon lords. Indoors, the player has to find a way through the maze of chambers, solving puzzles and defeating the minions of the Drakkhen. Party members are depicted in four status windows on the left side of the screen, thus allowing to see their current status and equipment at once.' FROM games WHERE igdb_id = 12057 ON CONFLICT (game_id, language_code) DO NOTHING;
