INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'J.R.R. Tolkien''s War in Middle Earth', 'J.R.R. Tolkien''s War in Middle Earth is the 16-bit game with additional adventuring features compared to the 8-bit version, loosely depicting the events of the One Ring from the Shire to Mt. Doom. The game starts with the three hobbits: Frodo, Sam, and Pippin surrounded by nine individual units of Nazgul near the Shire. Although the first task is to travel to Rivendell, the player is free to decide how heroes and armies progress, despite the in-game conventional storyline.' FROM games WHERE igdb_id = 7890 ON CONFLICT (game_id, language_code) DO NOTHING;
