INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetris', 'Tetris is a tile-matching puzzle video game. The goal is to place pieces made up of four tiles in a ten-by-twenty well, organizing them into complete rows, which then disappear. There are two game modes: A-Type and B-Type. A-Type is an endless marathon with increasing speed levels. B-Type is played at a fixed speed, with or without optional garbage blocks in the playfield, and a goal of clearing 25 lines.' FROM games WHERE igdb_id = 8197 ON CONFLICT (game_id, language_code) DO NOTHING;
