INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('herzog-zwei', 24073, '1989-12-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4tup.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/vbqpzxe3bvobnxzrkbso.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Herzog Zwei', 'Herzog Zwei is a Sega Genesis-exclusive game by Technosoft, published in 1989 (released in North America and Europe in early 1990). It is an early real-time strategy game, predating the genre-popularizing Dune II. Herzog Zwei combines the arcade-style play of Technosoft''s own Thunder Force series with a simple, easy-to-grasp level of strategy. In Herzog Zwei, the player directly pilots a flying, transforming mech, a multi-role robot suited for utility and combat. Through the mech, the player purchases surface combat units, airlifts them across the battlefield, and issues them orders. These command activities can only be performed through the mech. Vehicles follow their assigned orders (which are fairly basic: patrol, garrison, capture base) until they either run out of fuel or are destroyed. Tactical re-deployment (mission reassignment, vehicle repair) involves a great deal of micromanagement, due to the required involvement of the mech.' FROM games WHERE igdb_id = 24073 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 24073 AND ge.slug = 'real-time-strategy-rts' ON CONFLICT DO NOTHING;
