INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bandit Kings of Ancient China', 'Bandit Kings of Ancient China is a turn-based strategy role-playing simulation game developed and published by Koei for MS-DOS, the Amiga, and the Apple II. It was well-received at its inception, and was considered to be a significant step forward in the complexity of strategy gaming.' FROM games WHERE igdb_id = 9496 ON CONFLICT (game_id, language_code) DO NOTHING;
