INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bloodwych', 2434, '1989-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9cxx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aru6s.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bloodwych', 'The land of Trazere was once ruled by the powerful and benevolent organization of mages known as Bloodwych. Governed by the Grand Dragon, the Bloodwych supervised over the balance in the land, protecting it from evil and driving it to prosperity. However, the second-in-command of Bloodwych, named Zendick, turned against his group, banished his opponents to the astral plane, and began working on a mad plan - summon the ultimate evil, the Lord of Entropy. The player controls the champion of Trazere, whose ultimate goal is to stop Zendick and restore peace in the country. Bloodwych is an RPG in the style of Dungeon Master and Eye of the Beholder, being a 3D first-person maze-like game. This game''s distinguishing feature is the two-player split screen support, allowing simultaneous playing on one computer. Each player controls a party of four characters. The four basic classes are warrior, mage, adventurer, and thief; however, each class also has sub-classes, which are represented by four different colors. These colors come into play also when the characters learn and combine spells.' FROM games WHERE igdb_id = 2434 ON CONFLICT (game_id, language_code) DO NOTHING;
