INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Quest III: The Pirates Of Pestulon', 'Space Quest III: The Pirates of Pestulon continues the hilarious space-faring adventures of Roger Wilco, the unlikely hero and intergalactic garbageman. In this installment, players must unravel the mystery behind the disappearance of the "Two Guys from Andromeda," the fictional creators of the Space Quest series. As Roger, players navigate through a satirical sci-fi universe, facing off against the nefarious Pirates of Pestulon and possibly other suspects, including overzealous fans and revenge-seeking minions of previous villain Sludge Vohaul. With its blend of point-and-click adventure gameplay, cutting-edge graphics for its time, and trademark humor, Space Quest III challenges players to save the kidnapped game designers and thwart another galactic threat, all while delivering a self-aware, comical take on the adventure game genre and sci-fi tropes.' FROM games WHERE igdb_id = 30 ON CONFLICT (game_id, language_code) DO NOTHING;
