INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ironsword-wizards-and-warriors-ii', 48053, '1989-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6o0e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/xzye5mrlawnzelaeat70.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ironsword: Wizards & Warriors II', 'In Ironsword, the hero of the series, Kuros, must face off once again against the evil wizard Malkil, who has taken control of the four elementals of the world—wind, water, fire and earth. Each of the four elemental realms consists of two stages. In the first stage, Kuros must find a golden artifact which belongs to the Animal King of the realm; once accomplished, the path to the second part of the realm will appear. In the second stage, the goal is to find the magic spell which can be used to fight the elemental boss. Without the spell, it is impossible to damage the boss. Once the elemental in each stage has been destroyed, Kuros obtains a piece of the legendary Iron Sword, which is needed for the final battle on Icefire Mountain.' FROM games WHERE igdb_id = 48053 ON CONFLICT (game_id, language_code) DO NOTHING;
