INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Shark', 'In the arcade version, one summer night in 1991, an enemy fleet known as the Strange Fleet approached a small island of the Mediterranean Sea. When it arrived, very few saw the Strange Fleet. Two years later, while the Stranger Fleet expanded itself, it created a world war. It is unknown by everyone around the world who noticed the attacks of the Strange Fleet. As the Strange Fleet continues their assault, many against them cried "Fire Shark! Fire Shark! It''s time to take off!! Beat them for our sake. Go! Go! Fire Shark!" The North American release is based on the Japanese "Same! Same! Same!" 2-player version, but it also includes localized text and a minor reduction in the speed of enemy bullets.' FROM games WHERE igdb_id = 39647 ON CONFLICT (game_id, language_code) DO NOTHING;
