INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cyber Police ESWAT', 'The game is a sidescrolling platformer similar to Shinobi. The game is set in the near future, where the player controls a blonde police officer named Duke Oda who, over a series of levels, turns into the cyborg E.S.W.A.T. At first, as a rookie member of the Cyber Police force in the city of Liberty, the player has to clean the streets of an overwhelming crime wave and terminate the most wanted criminals. In the first and second levels of the game, the completely human Duke Oda can only utilize a single shot weapon and can only survive one hit. A second hit will kill him.' FROM games WHERE igdb_id = 6793 ON CONFLICT (game_id, language_code) DO NOTHING;
