INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sword of Sodan', 'Like Søren Grønbech''s other game Datastorm, Sword of Sodan was most noted on the technical side, as the sprites were large and distinctive-looking. Your task (as either a hero or heroine) is to dethrone the tyrannous Zoras the Necromancer, and avenge his killing of your father. There are 11 levels to take on, with indoor and outdoor settings. Your character has a range of sword-slashing and jumping moves, which must be used to their full effect if you are to make progress. The game features digitised sound and speech, as well as an action-replay feature, an unusual concept outside sports games at the time.' FROM games WHERE igdb_id = 4394 ON CONFLICT (game_id, language_code) DO NOTHING;
