INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chambers of Shaolin', 'In the first part of this game, you will have to train your character in the various chambers of Shaolin. Each exercise, which includes balancing on trees, kicking a pendulum and dodging objects coming towards you, will improve your skills like stamina and strength. The better you do in the chambers, the easier it will be for you in part two. Part two is a more traditional 2D fighting game where you have to advance from level to level by beating your opponents up.' FROM games WHERE igdb_id = 11997 ON CONFLICT (game_id, language_code) DO NOTHING;
