INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow Dancer', 'Shadow Dancer is an action platform game developed by Sega for the Sega System 18 arcade system in 1989. A port of the game was published by Sega for the Sega Master System, and ports to several home computers were published by U.S. Gold. It was the first sequel to Shinobi, alongside The Revenge of Shinobi. A similar game titled Shadow Dancer: The Secret of Shinobi was released for the Sega Mega Drive, which features an entirely different set of stages. A terrorist group is planting numerous time bombs throughout the city. The player, a ninja master accompanied by a canine partner, sets out on four missions to dismantle the bombs and destroy the criminal syndicate behind these acts.' FROM games WHERE igdb_id = 6876 ON CONFLICT (game_id, language_code) DO NOTHING;
