INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Psycho Fox', 'Psycho Fox must get to the right hand side of the level. However, there are many enemies in the way. He can use a Shinto stick to change into characters/animals like a hippopotamus, a monkey or a tiger, each of which has its own special ability. The hippopotamus is slow and cannot jump very high, but can punch through special destructible blocks in the game world. The monkey can jump higher than the other creatures and the tiger can run faster. Psycho also has an ally named Birdfly, who can be used as armor or as a boomerang. If Psycho is hit while carrying Birdfly, Birdfly goes away and the player does not lose a life.' FROM games WHERE igdb_id = 46131 ON CONFLICT (game_id, language_code) DO NOTHING;
