INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Final Fantasy Legend', 'The long-running FINAL FANTASY series hits the Game Boy with FINAL FANTASY LEGEND. Create your party by choosing four warriors from eight different character classes including humans, mutants, and monsters. Humans specialize in hand-to-hand combat and have access to most weapons, mutants wield magic like no other, and monsters can evolve themselves by feasting on the meat of fallen opponents to become new monsters! Venture your way through four different lands each with a unique fantasy theme to stop the wicked Ashura Devils from destroying the world. A beautiful fantasy soundtrack adds atmosphere to the experience and puts you in the right mood. This single-player RPG features battery backup to save your progress, and is compatible with both Game Boy and Game Boy Color. RPG fans on the go should check out FINAL FANTASY LEGEND.' FROM games WHERE igdb_id = 396 ON CONFLICT (game_id, language_code) DO NOTHING;
