INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blue-lightning--1', 74903, '1989-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3g3y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arxoa.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blue Lightning', 'Blue Lightning, a launch title for the Lynx, is an arcade flight game heavily based on After Burner. The player controls the prototype Blue Lightning jet in combat against the enemy. The game consists of nine missions with varied objectives. These range from shooting down enemy planes to taking out tanks and ships or radar installations. In a courier mission, documents must be delivered by landing on a certain airfield. Upon successfully completing a mission, a password is given. The action is seen from behind the Blue Lightning. With the heavy arcade focus, there is no danger of stalling or even crashing into the ground. Crashing into air or ground targets is possible, however. The Blue Lightning is armed with a cannon with unlimited ammunition and 40 missiles. The on-board computer automatically seeks missile lock for enemy targets while the cannon must of course be aimed manually. The Blue Lightning is also equipped with an afterburner: activating it puts the plane to maximum speed for ten seconds, allowing one to catch up to enemy targets that got away. After use it takes another ten seconds to recharge. The plane is also able to pull off a barrel roll, useful to lose the lock of enemy missiles.' FROM games WHERE igdb_id = 74903 ON CONFLICT (game_id, language_code) DO NOTHING;
