INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Friday the 13th', 'The game is a 2D action horror based on the first movie of popular horror franchise Friday the 13th. The game casts the player as one of six camp counselors (three girls or three boys) at the Camp Crystal Lake and the player´s main task is to defend the children in the cabins situated all around the lake while slowly killing Jason. The cabins are frequently attacked by the mass murderer and the player must get to the attacked cabin within the specific time limit otherwise Jason kills the children. When all the camp counselors or all the children are dead, the game is over. Jason can attack the player outside cabins too, on the pathways when exploring. There are three cycles meaning, Jason must be killed three times (every time Jason is stronger and quicker) to beat the game.' FROM games WHERE igdb_id = 8530 ON CONFLICT (game_id, language_code) DO NOTHING;
