INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Midnight Resistance', 'Midnight Resistance is a side-scrolling action shooting game produced by Data East for the arcades in 1989. The game was ported by Data East to the Sega Mega Drive in 1990 and by Ocean Software to various home computer platforms during the same year. The game is set in a dystopian future where the player controls a member of a resistance movement who goes on a mission to rescue his kidnapped family from a mad scientist.' FROM games WHERE igdb_id = 4401 ON CONFLICT (game_id, language_code) DO NOTHING;
