INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('budokan-the-martial-spirit', 4409, '1989-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/da3otev0bptsweazcxr4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/z7l8bv0qcdtuqxrqqemv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Budokan: The Martial Spirit', 'Walk the path of the warrior. Learn four classic martial arts- Karate, Kendo, Nunchaku and Bo. Combine power and grace into a dangerous black belt mix. Enter Tobiko Ryu Dojo. Your journey to the Bodokan begins here. Are you willing to endure the hard training it takes to be called a master? Tobiko Sensei observes your every action. Go to him for words on tactics, strategy, and guidance. Put your philosophy into action. Say hello to Goro-San. If you survive him, eleven others are ready to teach you the zen of defeat. If you don''t, it''s konban-wa (goodnight!). Do you fast attack for quick points or store up your ki (energy) for the devastating blow? Better decide before his Yari answers for you. Authentic Japanese/Okinawan martial arts- all arts and weapons based on real life. Unique player interface allows for over 25 moves per style. Twelve authentic martial arts styles, including Yari, Tonfa, Kusari-gama and Naginata.' FROM games WHERE igdb_id = 4409 ON CONFLICT (game_id, language_code) DO NOTHING;
