INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Indiana Jones and the Last Crusade: The Action Game', 'Indiana Jones and the Last Crusade: The Action Game is a side-scrolling action title based on the 1989 film of the same name. Players control Indiana Jones through various levels that loosely follow the movie’s plot, including iconic locations like the catacombs and the Zeppelin. Gameplay focuses on platforming, basic combat, and item collection, with limited lives and high difficulty. The graphics and sound vary across platforms, with the Amiga and Atari ST versions generally offering the most polished presentation.' FROM games WHERE igdb_id = 185 ON CONFLICT (game_id, language_code) DO NOTHING;
