INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Myth: History in the Making', 'In this platform game, you are a mere mortal who has been called by the Gods to defeat several mythological creatures that have been turned bad by the evil Dameron. Myth: History in the Making is a platform game with a lot of fighting. The levels of this game deal with different mythologies, from ancient Greece to the Vikings, over to Valhalla (where none other than the hammer-wielding Thor awaits you), and more.' FROM games WHERE igdb_id = 12187 ON CONFLICT (game_id, language_code) DO NOTHING;
