INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arch Rivals', 'Arch Rivals is a basketball game developed and published by Midway in 1989. The game introduces violence as an important part of the game, encouraging players to punch opposing players and stealing the ball from them. The game is regarded as the forerunner to Midway''s popular arcade basketball game, NBA Jam.' FROM games WHERE igdb_id = 4515 ON CONFLICT (game_id, language_code) DO NOTHING;
