INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sweet Home', 'Thirty years prior to the story in 1959, famous artist Ichirō Mamiya hid several precious frescos in his huge mansion before he mysteriously disappeared. In the present day, a team of five documentary filmers seek to recover the paintings from the abandoned, dilapidated mansion. Upon entering, they are trapped inside by the ghost of an unknown woman, who threatens to kill all trespassers. The team decides to split up and find a way out, but the mansion is both in danger of collapsing and is occupied by countless monsters.' FROM games WHERE igdb_id = 9426 ON CONFLICT (game_id, language_code) DO NOTHING;
