INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Slayer: The Legend of Heroes', 'In this epic role-playing game, you must guide Prince Logan all accross the beautiful and dngerious world of Isrenasa in the quest to regain his throne. This game features a huge world to explore and many companions to join you on your journey. This game features one of the largest quests and most advanced interface of any role-playing game for the TurboDuo system.' FROM games WHERE igdb_id = 5579 ON CONFLICT (game_id, language_code) DO NOTHING;
