INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Colonel''s Bequest', 'The Colonel''s Bequest is a character-driven graphic adventure game by Sierra On-Line. It was developed for Atari ST, Amiga, and MS-DOS in 1989. It was the first of the short-lived Laura Bow Mysteries series created by Roberta Williams. The thrill and suspense of The Colonel''s Bequest is unprecedented in animated adventure games. Never before has a plot been so complex, or characters so well developed. From the die-hard mystery fan, to the veteran 3-D adventurer, this game is not to be missed.' FROM games WHERE igdb_id = 12008 ON CONFLICT (game_id, language_code) DO NOTHING;
