INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bonk''s Adventure', 'Bonk''s Adventure was developed by Red Company and Atlus and released on the TurboGrafx-16 in 1989 before being ported to the NES, Game Boy and Amiga. It is a 2D platform game that became quite popular, with subsequent remakes and sequels spawning from the game. It was later included in Nintendo''s Virtual Console service as well as the PlayStation Store.' FROM games WHERE igdb_id = 7794 ON CONFLICT (game_id, language_code) DO NOTHING;
