INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stormlord', 'Badh the queen has imposed a terrible vengeance on the land by kidnapping the fairies. To restore things their rightful way, you must rescue them. As you progress through the levels of platform-adventure action, you will come across fairies which are rescued by touching them. Enemies include Venus Fly Traps, localized acid rain showers and dragons, which can be avoided or shot in the bonus shoot ''em up sections. You will need help to reach some levels; this comes from Mael Dvin the Eagle.' FROM games WHERE igdb_id = 12781 ON CONFLICT (game_id, language_code) DO NOTHING;
