INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rick Dangerous', 'The game is largely based on the Indiana Jones movie Raiders of the Lost Ark. Set in 1945, British agent Rick Dangerous travels to the Amazon jungle to search for the lost Goolu tribe. His plane crashes in the jungle, and Rick must escape from the enraged Goolu. When the game starts Rick finds himself in a cave running from a rolling boulder, a famous scene from the Indiana Jones movie. Armed with a pistol and dynamite, Rick must fight hostiles and evade countless traps in three more levels. The second level is set inside a pyramid in Egypt. In level three, Rick must venture to the Nazi stronghold of Schwarzendumpf castle to rescue captured Allied soldiers. The rescued soldiers tell him that the Nazis are planning a missile attack on London. Therefore, in the last level Rick must infiltrate their secret missile base.' FROM games WHERE igdb_id = 12202 ON CONFLICT (game_id, language_code) DO NOTHING;
