INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynamite Düx', 'Side-scrolling beat ''em ups in which you must rescue a trapped female friend are nothing unusual. Where this one stands out, however, is the setting of your character as a duck called Bin, and with motion having a clear waddling appearance. The enemies to fight are all from the animal kingdom, but somewhat warped - crocodiles with boxing moves and cows armed with rocket packs for example. Bin has six levels to clear before he can rescue Lucy from Archaca''s clutches.' FROM games WHERE igdb_id = 12730 ON CONFLICT (game_id, language_code) DO NOTHING;
