INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('final-fight', 1655, '1989-11-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4a0q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1kc8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fight', 'Final Fight is a side-scrolling beat-''em-up produced by Capcom. Final Fight can be played by up to two players simultaneously. Before the game begins, the player chooses between the three main characters: Haggar, Cody, and Guy. Each has his own fighting style and attributes. Health gauges are displayed for both player and enemy characters. The controls for Final Fight consist of an eight-way joystick and two buttons for attacking and jumping respectively. Pressing the attack button repeatedly when attacking an enemy or multiple enemies will cause the player character to perform a combo. The final blow of the combo can be changed to a throw if the player moves the joystick in the opposite direction just before landing it. The player can also perform a jump attack. Pressing the attack and jump buttons simultaneously allows the player to perform a special attack that strikes all surrounding enemies, but will drain a small portion of the player''s health. Enemies can be grabbed simply by walking into one of them. When an enemy is grabbed, the player can perform a grab attack by pressing the attack button or perform a throw by tilting the joystick left or right. A thrown enemy can be tossed at another for additional damage. Items such as weapons, health recovery items, and items awarding extra points can be picked up by standing over one and pressing the attack button. Weapons have limited uses and will disappear if the player is disarmed by an enemy too much or when the player moves to a new area. Final Fight consists of six stages or "rounds", as well as two bonus rounds. Each round takes place in a different section of Metro City such as the Slums and the Subway, with most rounds featuring more than one level. At the end of each round the player will face a boss character unique to that round.' FROM games WHERE igdb_id = 1655 ON CONFLICT (game_id, language_code) DO NOTHING;
