INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('chamber-of-the-sci-mutant-priestess', 81786, '1989-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6yky.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/vkgmdc4xhywbidyboefc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chamber of the Sci-Mutant Priestess', 'Chamber of the Sci-Mutant Priestess (originally entitled Kult: The Temple of Flying Saucers) is a puzzle-solving adventure game. To solve the puzzles, Raven will sometimes need to collect and trade items; but more often, usage of the eight "psi-powers" is required. These powers range from a simple light spell ("Solar Eyes") to instant-kill ("EV" - extreme violence) and complex psychological effects ("Brainwarp"). The five ordeals can be completed in any order, or even skipped altogether to reach a different ending. A time limit is imposed on the ordeals, and is calculated by turns. A "wait" command, which skips a turn, is also available.' FROM games WHERE igdb_id = 81786 ON CONFLICT (game_id, language_code) DO NOTHING;
