INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toki', 'The hero of the game is a young jungle-man named Toki. One day the evil wizard Dr. Stark kidnaps his girlfriend Wanda. When Toki tries to save her, he is turned into a monkey! Now Toki has to find Dr. Stark in his palace, rescue Wanda, and become a human being again!' FROM games WHERE igdb_id = 12228 ON CONFLICT (game_id, language_code) DO NOTHING;
