INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Batman: The Video Game', 'Batman: The Video Game, is a group of platform games developed by Sunsoft for the Nintendo Entertainment System and Game Boy, loosely based on the 1989 film of the same name. Despite having the same title, each is actually a different game. The NES title is arguably the best known and contains five levels culminating in a final showdown with the Joker in the bell tower of Gotham Cathedral. It was received well despite changes from the movie upon which it was based. Sunsoft later released Batman: Return of the Joker as a follow-up which is not related to any movie.' FROM games WHERE igdb_id = 49226 ON CONFLICT (game_id, language_code) DO NOTHING;
