INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Military Madness', 'Military Madness (released as Nectaris in Japan) is a futuristic turn-based strategy war game. The year is 2089 and the setting is Earth’s moon, which yields many important resources. While the governments of Earth bicker over their staked claims on the moon, the evil Axis Empire launches a lunar military campaign and takes over the moon, using its factories to produce advanced weaponry, the most devastating of which is the SAM (Supreme Atomic Missile). As commander of the Allied forces, it is the player’s responsibility to lead what’s left of the Allied armies in a desperate offensive against the Axis Empire on the lunar surface before they can use the SAM to destroy Earth.' FROM games WHERE igdb_id = 44334 ON CONFLICT (game_id, language_code) DO NOTHING;
