INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ivan-ironman-stewarts-super-off-road', 12735, '1989-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2sb5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/uey9p9lvjurbazcy1am3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ivan ''''Ironman'''' Stewart''s Super Off Road', 'Enter the world of off-road racing as 4 vehicles will face each other, on a series of tracks which are based around flipped and reversed versions of a core selection. Fame, glory and bikini clad women await your victories and the taste of dirt awaits if you fail. Let a computer car beat you and you lose one of your 3 credits. Successful races bring more money, which can be used to soup up their machine. Boosts to top speed, grip and acceleration can be purchased, and your nitro boost must be kept topped up. If you are desperate for upgrades, you can buy into your spare credits. Only your off-road driving abilities will be enough to pull you to first place in these races. Play alone or with up to 3 other players (depending on the version) in this classic arcade game.' FROM games WHERE igdb_id = 12735 ON CONFLICT (game_id, language_code) DO NOTHING;
