INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phantasy Star II', 'Gameplay is similar to the original Phantasy Star, the first game in the series. Its battle system is turn-based, allowing the player to choose commands for their party of up to four characters. Each of the eight characters has a different set of preferred weapons and armor, as well as techniques, suited to the character''s job. The player must defeat enemies in the overworld and in dungeons to advance in the game. The game abandoned the first-person view that the first game used for dungeons and battles. Phantasy Star II instead uses a top-down perspective for exploration and a third-person view in battles.' FROM games WHERE igdb_id = 1232 ON CONFLICT (game_id, language_code) DO NOTHING;
