INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Advanced Dungeons & Dragons: Hillsfar', 'Hillsfar: An incredible fantasy that combines the best of role-playing adventures and fast-paced action games.* Every visit to Hillsfar is a different, exhilarating experience. Explore the city, meet its colorful denizens on the streets or in pubs and discover a quest (there are many possible ones). Transfer your favorite character from the Pool of Radiance or Azure Bonds AD&D role-playing games, or create one from scratch. Your quest and the options available to you each game will change to suit your character''s specialty (thief, mage, cleric or fighter). Your quest will keep you constantly on the move. Fight in the arena against raging minotaurs, ill-tempered orcs or insulted swordsmen. Enter different buildings and your maze-running and lock-picking skills will be required. Archery and equestrian events may also be part of your overall quest. Think fast. Move fast. These mini-games happen in real time! For both adventure and action, there''s no place like Hillsfar!' FROM games WHERE igdb_id = 8622 ON CONFLICT (game_id, language_code) DO NOTHING;
