INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sword-of-the-samurai', 9218, '1989-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5xio.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7ov.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sword of the Samurai', 'Enter Japan in the Age of Warring States. At the center of this role-playing, action-adventure simulation of combat, statesmanship and intrigue, you are a samurai warrior struggling for Honor. More important than life itself, Honor is crucial to achieving your ultimate goal: unifying the country under your noble rule. In Sword of the Samurai, you will be part of the culture of feudal Japan, and you must learn to live by its rules. To succeed as a samurai, you must think like the samurai. Learn when to leave your sword in its sheath, when to draw it - and what to do with it once it’s drawn. You will fight duels, lead troops on the battlefields, and defend your family against assassins and kidnappers. If you are courageous and honorable, you may advance to become the head of your clan, and warlord of your province. If you master diplomacy and generalship, and outmaneuver your rivals, you may even become Shogun - absolute ruler of Japan. But remember that in all cultures power corrupts - and those who seek absolute power don’t always play by the rules.' FROM games WHERE igdb_id = 9218 ON CONFLICT (game_id, language_code) DO NOTHING;
