INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Batman', 'The movie of the decade is now the game of the year!  Just when you thought you''d heard the last of his heinous cackling, The Joker is back in an all new action-adventure, based on the blockbuster movie - Batman.  As the Dark Knight, only you can determine how the plot will unfold as you try to save Gotham City from certain doom. Even with the Batwing and all your wonderful toys, The Joker may just rewrite your script.  So, rev up the Batmobile and get ready for the chase of your life.' FROM games WHERE igdb_id = 14288 ON CONFLICT (game_id, language_code) DO NOTHING;
