INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '688 Attack Sub', '688 Attack Sub is a classic modern submarine simulation which puts you in command of either the American Los Angeles or the Soviet Alfa class nuclear-powered submarines. Most of the systems you would expect such as sonar and periscope are featured and nicely presented in VGA. The game offers ten missions for both the Soviet and American side in a Cold War scenario, that grows progressively hotter. Nice to see that the two sides'' submarines have their own graphic sets in the game, even with some pseudo-cyrillic labels on the Russian side.' FROM games WHERE igdb_id = 5338 ON CONFLICT (game_id, language_code) DO NOTHING;
