INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('disneys-ducktales--2', 6487, '1989-09-14', 86, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wks.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7n0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s DuckTales', 'DuckTales is a platform game developed and published by Capcom and based on the Disney animated TV series of the same name. It was first released in North America for the Nintendo Entertainment System in 1989 and was later ported to the Game Boy in 1990. The story involves Scrooge McDuck traveling around the globe collecting treasure and outwitting his rival Flintheart Glomgold to become the world''s richest duck. Produced by key personnel from the Mega Man series, DuckTales would go on to sell over a million copies worldwide on each system, becoming Capcom''s best-selling title for both platforms. The game was praised for its tight control, unique and non-linear gameplay and bright presentation, and is often regarded as one of the best titles for the NES, appearing on numerous "Best of" lists.' FROM games WHERE igdb_id = 6487 ON CONFLICT (game_id, language_code) DO NOTHING;
