INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nuclear War', 'As leader of a global power in a fictional world, you must lead your nation to victory by being the last remaining country in the world. You must use every means at your disposal to win, whether it be through the cunning use of propaganda campaigns or through the devastating force of a tactical nuclear strike. You must take advantage of the weak and scheme against the mighty to insure your place as the ultimate victor.' FROM games WHERE igdb_id = 12189 ON CONFLICT (game_id, language_code) DO NOTHING;
