INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WWF Superstars', 'WWF Superstars is an arcade game manufactured by Technōs Japan and released in 1989. It is the first WWF arcade game to be released. A series of unrelated games with the same title were released by LJN for the original Game Boy. Technōs followed the game with the release of WWF WrestleFest in 1991.' FROM games WHERE igdb_id = 39424 ON CONFLICT (game_id, language_code) DO NOTHING;
