INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Untouchables', 'You are The Untouchables in this side-scrolling action game. Play as Elliot Ness after the ruthless Mafia boss Al Capone. You have various tasks throughout the six levels and a variety of weapons to pick up such as a shotgun or tommy gun. Watch out for Capone''s henchmen though.' FROM games WHERE igdb_id = 12807 ON CONFLICT (game_id, language_code) DO NOTHING;
