INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetris', 'Tengen, an Atari label, released an unlicensed version of Tetris for the Nintendo Entertainment System. After they lost a lawsuit to Nintendo, which acquired the rights from Russia to port the game to home consoles (they already had the handheld consoles rights), Tengen had to destroy every spare cartridge unsold at the time. The Tengen game featured a two-player simultaneous mode not available in Nintendo''s version' FROM games WHERE igdb_id = 180278 ON CONFLICT (game_id, language_code) DO NOTHING;
