INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galaxy Force', 'CAUTION: FOUR MEGA POWER! Not double, not triple, but FOUR times the playing power of a regular cartidge. You get the hottest space combat, the baddest explosions, and the coolest sounds ever! Journey to four different planets, each with stunning but deadly landscapes. There''s so many awesome enemies, you won''t have time to stargaze!' FROM games WHERE igdb_id = 45651 ON CONFLICT (game_id, language_code) DO NOTHING;
