INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Denaris', 'Katakis was the first R-Type-influenced side scrolling shoot ''em up. You control the H-75 Eagle Fighter, against the machines which have over-ran a peaceful planet, with satellite and collect power-ups through 12 levels. Each of these has lots of parallax scrolling and some direct influences from films including Aliens and The Terminator.' FROM games WHERE igdb_id = 12047 ON CONFLICT (game_id, language_code) DO NOTHING;
