INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turbo OutRun', 'The sequel to OutRun features similar basic gameplay to the original, with the action viewed from behind the car, and the challenge being to complete each stage within the time limit. Contact can cause the car to spin, slow down or even flip; in each case you will lose time. There are 16 stages set across the US, gradually moving from east to west, all depicted differently visually. After every 4 levels, you go into a shop screen, with a choice of upgrades. As the title implies, you now have a turbo booster installed, which speeds up the car, although over-use can cause the engine to overheat, and it is not recharged until each shop section. You have 5 continues, and failure to complete the course within the time limit costs you one.' FROM games WHERE igdb_id = 2053 ON CONFLICT (game_id, language_code) DO NOTHING;
