INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('r-type-ii', 6854, '1989-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2z0j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scpjmk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'R-Type II', 'The game is the sequel to R-Type, which was first released as an arcade game in 1987 and profoundly influenced later shooting games with its charge shots, unique weaponry, and grotesque enemies. Hudson Soft ported the later 4 levels of the original R-Type to the PC Engine with the title R-Type II, but the Hudson release is unrelated to the game described in this article. The player controls a ship called the R-9C (or R-9 Custom), which is an improved version of its predecessor game''s ship; the R-9. The ship''s design was changed slightly, and the wave cannon was given homing capabilities. Two new types of weapons (the Search Laser and Shotgun Laser) were added, bringing the total number of weapon types up to five. A new anti-ground unit bomb was also added to the missile inventory. Though the number of levels was decreased from the prequel, the number of enemies, their durability, and the number of bullets they shoot were greatly increased. Enemy movements and terrain were also made trickier, bringing the game''s difficulty up considerably. The same revival system is used as in the prequel, where the player is brought back to a checkpoint whenever their ship is destroyed. The controls are mostly unchanged from R-Type, where the 8-way joystick controls the ship''s movement, and the shot button fires the ship''s main beam. The other button is used to equip or unequip Force; the series'' most unusual innovation. Pressing down the shot button causes the blue beam gauge to fill up, and releasing the button causes a wave beam to travel a certain distance depending on the length of time the button was pressed down. If the button is pressed down until the blue gauge is fully charged, a red gauge appears and fills up quickly. Filling up the red gauge causes it to flash blue and red, releasing the shot button at this point shoots an even more powerful beam. Unlike the normal beam that only travels in a straight line, the newly added Shotgun Laser beam explodes in multiple directions after traveling a short distance. This shot causes heavy damage if the player can target a single enemy with it. However, holding the button down after the gauge is flashing causes the beam to return to the normal transverse beam (the gauge alternates between flashing and returning to the normal state while the button is held down), so the player must release the button at the right timing in order to successfully target enemies. The other newly added beam, the Search Laser, is semi-homing, and can bend at angles up to 45°.' FROM games WHERE igdb_id = 6854 ON CONFLICT (game_id, language_code) DO NOTHING;
