INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('a-10-tank-killer', 14200, '1989-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa6ii.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3we7.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A-10 Tank Killer', 'This simulation puts you in the cockpit of the A-10 Thunderbolt II, which is also known as the "Warthog". As the game''s name implies, it is used mainly to weaken enemy tanks, but also for destroying roads and bridges. You are armed with Avenger 30mm cannons which can fire around 70 times a second. Multiple camera angles are featured. Landing is automated and an accelerated time function is on offer. Characters have full AI to act without your involvement, and will communicate with you in-flight. Actions in one mission affect another - something you failed to destroy in one mission can attack you later.' FROM games WHERE igdb_id = 14200 ON CONFLICT (game_id, language_code) DO NOTHING;
