INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beast Busters', 'The longest day of your life... All hope abandon ye who enter here! Bloodthirsty monsters, mad scientists and diabolical traps await you in this city... Dr. Spektor''s fiendish creatures will do their utmost to destroy you- you must be the strongest and the fastest to escape a gory doom! From their original video arcades, the Beast Busters creatures have come to invade your screens. Can you handle it?' FROM games WHERE igdb_id = 11951 ON CONFLICT (game_id, language_code) DO NOTHING;
