INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'S.C.I.: Special Criminal Investigation', 'Chase H.Q. II- Special Criminal Investigation- continuing where Chase H.Q. left off. Your mission is to track down, chase and apprehend the dangerous criminals. It''s faster- explosive power sends you bulleting through various terrains- hold the line or plough the field! It''s tougher- the criminals wield some heavy hardware- but so do you! You can shoot but you must dodge their flak... heavy gunfire, trucks unloading their cargo onto your bonnet... it''s the meanest pursuit game to hit the micro screen. The extra features will leave you gasping for extended play- weather changes, bodyguard squads, grenade lobbing bikers, gun-choppers... just play it!... we dare you to stop!' FROM games WHERE igdb_id = 11999 ON CONFLICT (game_id, language_code) DO NOTHING;
