INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Street Rod', 'Year is 1963 and you''re one of the hotshots aspiring to be king of the county. You''re given a small sum of money to buy your first car. Tune it for maximum performance and off you go. In the diner where other hotshots are waiting to take your prized possession, you race for money and pink slips and if you win, you get to take home their cars!' FROM games WHERE igdb_id = 19229 ON CONFLICT (game_id, language_code) DO NOTHING;
