INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('a-nightmare-on-elm-street', 40935, '1989-08-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xu6.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Nightmare on Elm Street', 'A Nightmare of Elm Street is an action game based on the movie of the same name, where the player attempts to free friends from the grasp of the evil Freddy Krueger. Find a way into Freddy''s house on Elm Street, enter the Nightmare World, and fight him with unique powers or die trying! Before the game begins, the player must first choose one of available five characters in an attempt to free Joey who, as informed by this selection screen, has been already been captured by Freddy. Spending too much time during this section will allow Freddy to capture random character, until all but one selectable character is left, so choose a character quickly! When a character is selected, all the other characters are deemed captured by Freddy and must also be rescued. Each character has a different Soul mater and Power meter rating, as well as unique abilities. Soul represents the player''s health and if it runs out, the player dies. Power is used up every time the player uses a special ability.' FROM games WHERE igdb_id = 40935 ON CONFLICT (game_id, language_code) DO NOTHING;
