INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baseball Stars', 'Baseball Stars has become one of the most influential games in the development of sports video games since it was first released in 1989 by SNK. it was released for the Nintendo Entertainment System, as well as the PlayChoice 10 Upright Arcade Cabinet, and became a huge success throughout the world. It is often referred to as the best baseball game on the NES platform, and introduced a number of key features that have become standard in modern sports games, such as "create player" and "create team" functions.' FROM games WHERE igdb_id = 9903 ON CONFLICT (game_id, language_code) DO NOTHING;
