INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boomer''s Adventure in Asmik World', 'This video game stars Boomer (Asmik-kun in the Japanese version), a pink dinosaur, coursing through maze-like levels. Boomer traps enemies by digging holes and letting the enemy fall in them. Boomer can also dig out items and keys needed to complete the levels. Passwords are revealed before and after every boss level. On the top floor is the ultimate boss. Defeat him in order to beat the game.' FROM games WHERE igdb_id = 7797 ON CONFLICT (game_id, language_code) DO NOTHING;
