INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Willow', 'The version of Willow released for the Nintendo Entertainment System and the Famicom is an adventure game in the vein of The Legend of Zelda. The game has the player taking on the role of Willow. Unlike the film and arcade game, Willow generally travels alone, only briefly meeting other characters. In the tradition of The Legend of Zelda, Willow wields a sword and shield and many supplementary items along with a wide variety of magic spells. As the game progresses and Willow defeats enemies, he gains experience points and levels as in a role-playing video game.' FROM games WHERE igdb_id = 6981 ON CONFLICT (game_id, language_code) DO NOTHING;
