INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F-15 Strike Eagle II', 'The second in the series features campaigns in Lybia, the Persian Gulf, The Middle East and Vietnam, making for a total of 250,000 miles of potential action and danger. Primary and secondary aerial and ground-based targets must be destroyed on each of these. You are armed with a cannon, AMRAAM long-range air-to-air missile, Sidewinder short-range air-to-air missile, and the Maverick air-to-ground missile.' FROM games WHERE igdb_id = 12084 ON CONFLICT (game_id, language_code) DO NOTHING;
