INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prince of Persia', 'The game is set in ancient Persia. While the sultan is fighting a war in a foreign land, his vizier Jaffar, a wizard, seizes power. Jaffar''s only obstacle to the throne is the Sultan''s daughter (although the game never specifically mentions how). Jaffar locks her in a tower and orders her, under threat of execution, to become his wife. The game''s nameless protagonist, whom the Princess loves, is thrown into the palace dungeons. The player must lead the protagonist out of the dungeons and to the palace tower, defeating Jaffar and freeing the Princess in under 60 minutes. In addition to guards, various traps and dungeons, the protagonist is further hindered by his own doppelgänger, an apparition of his own self that is conjured out of a magic mirror.' FROM games WHERE igdb_id = 2472 ON CONFLICT (game_id, language_code) DO NOTHING;
