INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MechWarrior', 'MechWarrior is the first video game released in the BattleTech game series. MechWarrior was the first video game to offer the player a chance to pilot a BattleMech from the view of a pilot (a MechWarrior). With this game the player has a great deal of freedom when compared to many of the follow-up MechWarrior games, which include choosing missions, buying & selling ''Mechs and parts, hiring lance-mates, and traveling throughout the Inner Sphere. Underneath the major game mechanics, the player had the option of following a role playing style story arc that would unfold over a five-year (game time) period.' FROM games WHERE igdb_id = 13091 ON CONFLICT (game_id, language_code) DO NOTHING;
