INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow of the Beast', 'Shadow of the Beast is a platform game developed by Reflections and published by Psygnosis in 1989. The original version was released for the Amiga and later ported to many other systems. The game was known for its graphics, with many colours on screen and up to twelve levels of parallax scrolling backdrops, and its atmospheric score composed by David Whittaker, which used high-quality instrument samples.' FROM games WHERE igdb_id = 5434 ON CONFLICT (game_id, language_code) DO NOTHING;
