INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Where in Time is Carmen Sandiego?', 'Carmen Sandiego and her gang are loose once again, and it is the players job to capture her! This time around the player not only has to find where she is, but also when she is. Traveling to various locations, they need to assemble clues by questioning witnesses and searching locations to close in and capture Carmen Sandiego. Included with the game is The New America Desk Encyclopedia to help make clues more meaningful (and act as a form of copy protection!).' FROM games WHERE igdb_id = 4376 ON CONFLICT (game_id, language_code) DO NOTHING;
