INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xenon 2: Megablast', 'No-one likes a and loser. And no-one comes more universally despised than Xenites. For a thousand years they have been plotting revenge for their humiliating defeat in the last Galactic Conflict. Now the very fabric of time is in danger. The Xenites have planted five Time Bombs through history. Only you can save the day - not to mention the Universe. The last time you met it was a playground scrap. This time it is war.' FROM games WHERE igdb_id = 12236 ON CONFLICT (game_id, language_code) DO NOTHING;
