INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Populous', 'Populous is a real-time strategy game where the player takes the role of a deity influencing the development of civilizations. You shape terrain, guide followers, and use natural disasters like floods, volcanoes, and earthquakes to influence or eliminate opposing tribes. The game features an isometric perspective and includes 500 levels (worlds), each with different challenges. Originally developed by Bullfrog and designed by Peter Molyneux, it is considered one of the earliest examples of the god-game genre.' FROM games WHERE igdb_id = 248 ON CONFLICT (game_id, language_code) DO NOTHING;
